import java.util.*;

class Solution {
    public int minimumOperations(List<Integer> nums) {
        int[] dp = new int[4];
        for (int x : nums) {
            int[] nextDp = new int[4];
            nextDp[1] = dp[1] + (x == 1 ? 0 : 1);
            nextDp[2] = Math.min(dp[1], dp[2]) + (x == 2 ? 0 : 1);
            nextDp[3] = Math.min(dp[1], Math.min(dp[2], dp[3])) + (x == 3 ? 0 : 1);
            dp = nextDp;
        }
        return Math.min(dp[1], Math.min(dp[2], dp[3]));
    }
}

