var minimumOperations = function(nums) {
    let dp = [0, 0, 0, 0];
    for (const x of nums) {
        const nextDp = [0, 0, 0, 0];
        nextDp[1] = dp[1] + (x === 1 ? 0 : 1);
        nextDp[2] = Math.min(dp[1], dp[2]) + (x === 2 ? 0 : 1);
        nextDp[3] = Math.min(dp[1], dp[2], dp[3]) + (x === 3 ? 0 : 1);
        dp = nextDp;
    }
    return Math.min(dp[1], dp[2], dp[3]);
};
